/**
 * @summary Get active War Room session
 */
export const getGetActiveWarRoomUrl = (params?: GetActiveWarRoomParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/warroom/active?${stringifiedParams}` : `/api/warroom/active`
}

